284					cdStarted = true;
285				}
286				if ((skillData.GetValue<float>("cooldown") == 0f && overrideValue == -1f) || parent == null || parent.gameObject == null || !parent.gameObject.activeSelf)
287				{
288					return;
289				}
290				if (isChargeSkill)
291				{
292					if (expendCharge && cooldownRef.chargeCount > 0)
293					{
294						cooldownRef.chargeCount = Mathf.Max(0, cooldownRef.chargeCount - ((!(overrideValue > 0f)) ? 1 : ((int)overrideValue)));
295					}
296					parent.StartCoroutine(parent.cooldownManager.StartChargeCounter(skillID));
297				}
298				else
299				{
300					parent.cooldownManager.StartCooldownTimer(skillID, overrideValue);
301				}
302			}
