using System;
using System.Collections;
using UnityEngine;

public class ExplosionOnKill : ExplosionOnKillChance
{
	public new static string staticID = "ExplosionOnKill";

	private NumVarStatMod hurtMod;

	protected override string ExtraInfo => PercentToStr(hurtMod, "+");

	public ExplosionOnKill()
	{
		ID = staticID;
		category = Category.Misc;
		isCursed = true;
		hubOnly = true;
		explosionChance = 1f;
		explosionRadius = 2.5f;
		hurtMod = new NumVarStatMod(ID, 0.25f, 10, VarStatModType.Multiplicative);
	}

	public override void SetModStatus(bool givenStatus)
	{
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			if (!(player == null))
			{
				player.health.damageTakenStat.Modify(hurtMod, givenStatus);
				player.absEnemyKillEventHandlers = (Player.AbsEnemyKillEventHandler)Delegate.Remove(player.absEnemyKillEventHandlers, new Player.AbsEnemyKillEventHandler(OnKillEvent));
				if (givenStatus)
				{
					player.absEnemyKillEventHandlers = (Player.AbsEnemyKillEventHandler)Delegate.Combine(player.absEnemyKillEventHandlers, new Player.AbsEnemyKillEventHandler(OnKillEvent));
				}
			}
		}
	}

	public override void HandleKillEvent(Entity givenEntity, AttackInfo givenInfo)
	{
		if (parentEntity != null)
		{
			parentEntity.StartCoroutine(DelayedExplosion(givenEntity.hurtBoxTransform, givenEntity.hurtBoxTransform.position));
		}
	}

	private IEnumerator DelayedExplosion(Transform givenTrans, Vector3 givenPosition)
	{
		yield return Globals.waitFor0p15;
		CreateExplosion(ID, (!(givenTrans == null)) ? givenTrans.position : givenPosition);
	}
}
