using UnityEngine;

public class ParryStun : OnParryItem
{
	public static string staticID = "ParryStun";

	private NumVarStatMod stunMod;

	public ParryStun()
	{
		ID = staticID;
		category = Category.Defense;
		parentCombineID = ParrySet.staticID;
		isCursed = true;
		stunMod = new NumVarStatMod(ID, 0.75f, 10, VarStatModType.Multiplicative);
	}

	public override void SetHandlers(bool givenStatus)
	{
		if (SetParentAsPlayer())
		{
			if (givenStatus && parentPlayer.inventory.ContainsItem(ParryHeal.staticID))
			{
				parentPlayer.inventory.AddItem(ParrySet.staticID, showNotice: false, ignoreMax: true);
				parentPlayer.inventory.RemoveItem(ParryHeal.staticID);
				parentPlayer.inventory.RemoveItem(staticID, forceOverride: true);
			}
			else
			{
				base.SetHandlers(givenStatus);
				parentPlayer.health.hitStunModifierStat.Modify(stunMod, givenStatus);
			}
		}
	}

	public override void OnParry(AttackInfo givenInfo, Vector2 givenInputVec)
	{
		if (IsNewParry)
		{
			Globals.ChaosInst<StunBurst>(StunBurst.Prefab, null, parentPlayer.attackOriginTrans.position).attack.SetAttackInfo(parentPlayer.skillCategory, ID);
		}
	}
}
