using UnityEngine;

public class ParryTrio : OnParryItem
{
	public static string staticID = "ParryTrio";

	public ParryTrio()
	{
		ID = staticID;
		category = Category.Defense;
		combineOnly = true;
	}

	public override void OnParry(AttackInfo givenInfo, Vector2 givenInputVec)
	{
		if (IsNewParry)
		{
			parentPlayer.health.RestoreHealth(20);
			Object.Instantiate(HealthPowerup.EffectPrefab, parentPlayer.transform.position, Quaternion.identity, parentPlayer.transform);
			Vector2 vector = parentPlayer.attackOriginTrans.position;
