6525					}
6526				}
6527				if (!isStealthed)
6528				{
6529					if (parent.playerLight != null)
6530					{
6531						parent.playerLight.intensity = parent.currentLightIntensity;
6532					}
6533					if (parent.spriteRenderer != null)
6534					{
6535						spriteColor.a = 1f;
