6504					yield break;
6505				}
6506				isStealthed = true;
6507				GameController.allies.Remove(player.gameObject);
6508				while (!ChaosStopwatch.Check(stealthStopwatchID))
6509				{
6510					yield return null;
6511				}
6512				isStealthed = false;
6513				if (player.gameObject != null && !player.fsm.currentStateName.Contains("Dead"))
6514				{
6515					GameController.allies.Add(player.gameObject);
6516				}
6517				if (parent.playerLight != null && parent.spriteRenderer != null)
6518				{
6519					while (!isStealthed && parent.playerLight.intensity <= parent.currentLightIntensity)
6520					{
6521						parent.playerLight.intensity += Time.deltaTime * 5f;
6522						spriteColor.a += Time.deltaTime * 2f;
6523						parent.spriteRenderer.color = spriteColor;
6524						yield return null;
6525					}
6526				}
6527				if (!isStealthed)
6528				{
6529					if (parent.playerLight != null)
6530					{
6531						parent.playerLight.intensity = parent.currentLightIntensity;
6532					}
6533					if (parent.spriteRenderer != null)
6534					{
6535						spriteColor.a = 1f;
6536						parent.spriteRenderer.color = spriteColor;
6537					}
6538				}
6539			}
