11871			private IEnumerator HandleStatis()
11872			{
11873				Attack newAttack = Globals.ChaosInst<Attack>(Attack.CirclePrefab, null, parent.transform.position);
11874				newAttack.SetAttackInfo(parent.skillCategory, staticID);
11875				((CircleCollider2D)newAttack.collider).radius = stasisRadius;
11876				newAttack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(newAttack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnEntityCollision));
11877				yield return null;
11878				UnityEngine.Object.Destroy(newAttack.gameObject);
11879				enemies.RemoveAll((Enemy e) => e == null);
11880				if (enemies.Count == 0)
11881				{
11882					yield break;
11883				}
11884				for (int num = 0; num < enemies.Count; num++)
11885				{
11886					if (!(enemies[num] == null))
11887					{
11888						enemies[num].enabled = false;
11889						enemies[num].spriteRenderer.color = new Color(0.7f, 0.6f, 1f, 0.5f);
11890						Health health = enemies[num].health;
11891						health.takeDamageEnterHandlersWithHurtEntity = (Health.OnTakeDamageHandlerWithHurtEntity)Delegate.Combine(health.takeDamageEnterHandlersWithHurtEntity, new Health.OnTakeDamageHandlerWithHurtEntity(HijackAttackInfo));
11892					}
11893				}
11894				stasisTimer.IsRunning = true;
11895				while (stasisTimer.IsRunning)
11896				{
11897					yield return null;
11898				}
11899				for (int num2 = 0; num2 < enemies.Count; num2++)
11900				{
11901					if (!(enemies[num2] == null))
11902					{
11903						enemies[num2].enabled = true;
11904						enemies[num2].spriteRenderer.color = Color.white;
11905						Health health2 = enemies[num2].health;
11906						health2.takeDamageEnterHandlersWithHurtEntity = (Health.OnTakeDamageHandlerWithHurtEntity)Delegate.Remove(health2.takeDamageEnterHandlersWithHurtEntity, new Health.OnTakeDamageHandlerWithHurtEntity(HijackAttackInfo));
11907					}
11908				}
11909				int atkCounter = 0;
11910				for (int i = 0; i < maxAtkCounter; i++)
11911				{
11912					foreach (KeyValuePair<Entity, List<AttackInfo>> atkEntry in atkHistory)
11913					{
11914						List<AttackInfo> atkList = atkEntry.Value;
11915						if (atkList != null && atkList.Count > atkCounter)
11916						{
11917							atkEntry.Key.health.TakeDamage(atkList[atkCounter]);
11918							atkCounter++;
11919							yield return new WaitForSeconds(0.05f);
11920						}
11921					}
11922				}
11923			}
11924		}
