11871			private IEnumerator HandleStatis()
11872			{
11873				Attack newAttack = Globals.ChaosInst<Attack>(Attack.CirclePrefab, null, parent.transform.position);
11874				newAttack.SetAttackInfo(parent.skillCategory, staticID);
11875				((CircleCollider2D)newAttack.collider).radius = stasisRadius;
11876				newAttack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(newAttack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnEntityCollision));
11877				yield return null;
11878				UnityEngine.Object.Destroy(newAttack.gameObject);
11879				enemies.RemoveAll((Enemy e) => e == null);
11880				if (enemies.Count == 0)
11881				{
11882					yield break;
11883				}
11884				for (int num = 0; num < enemies.Count; num++)
11885				{
11886					if (!(enemies[num] == null))
11887					{
11888						enemies[num].enabled = false;
