11892					}
11893				}
11894				stasisTimer.IsRunning = true;
11895				while (stasisTimer.IsRunning)
11896				{
11897					yield return null;
11898				}
11899				for (int num2 = 0; num2 < enemies.Count; num2++)
11900				{
11901					if (!(enemies[num2] == null))
11902					{
11903						enemies[num2].enabled = true;
11904						enemies[num2].spriteRenderer.color = Color.white;
11905						Health health2 = enemies[num2].health;
11906						health2.takeDamageEnterHandlersWithHurtEntity = (Health.OnTakeDamageHandlerWithHurtEntity)Delegate.Remove(health2.takeDamageEnterHandlersWithHurtEntity, new Health.OnTakeDamageHandlerWithHurtEntity(HijackAttackInfo));
11907					}
11908				}
11909				int atkCounter = 0;
11910				for (int i = 0; i < maxAtkCounter; i++)
11911				{
11912					foreach (KeyValuePair<Entity, List<AttackInfo>> atkEntry in atkHistory)
11913					{
11914						List<AttackInfo> atkList = atkEntry.Value;
11915						if (atkList != null && atkList.Count > atkCounter)
11916						{
11917							atkEntry.Key.health.TakeDamage(atkList[atkCounter]);
11918							atkCounter++;
11919							yield return new WaitForSeconds(0.05f);
11920						}
11921					}
11922				}
11923			}
