public class GravityVortex : Projectile
{
	private static GameObject prefab;

	[HideInInspector]
	public float vortexDuration;

	[HideInInspector]
	public bool detonated;

	public GravityEffector gravityEffector;

	private Collider2D attackCollider;

	private Collider2D gravityCollider;

	private ParticleSystem lightDebrisEmitter;

	private ParticleSystem lightStreakEmitter;

	private AudioSource audioSource;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/GravityVortex.prefab"));

	public override void Awake()
	{
		base.Awake();
		detonated = false;
		attackBox.enabled = false;
		attackCollider = base.transform.Find("AttackBox").GetComponent<Collider2D>();
		attackCollider.enabled = false;
		Transform transform = base.transform.Find("GravityEffector");
		gravityEffector = transform.GetComponent<GravityEffector>();
		gravityEffector.enabled = false;
		gravityCollider = transform.GetComponent<Collider2D>();
		gravityCollider.enabled = false;
		transform = base.transform.Find("GravityVortexEffect");
		lightDebrisEmitter = transform.Find("DebrisSuctionEmitter").GetComponent<ParticleSystem>();
		lightStreakEmitter = transform.Find("LightStreakEmitter").GetComponent<ParticleSystem>();
	}

	public void Detonate()
	{
		if (!detonated)
		{
			anim.Play("Activated");
			attackCollider.enabled = true;
			gravityCollider.enabled = true;
			attackBox.enabled = true;
			gravityEffector.enabled = true;
			moveVector = Vector2.zero;
			lightStreakEmitter.enableEmission = true;
			lightDebrisEmitter.enableEmission = true;
			ChaosStopwatch.Refresh(flyStopwatchID, vortexDuration);
			audioSource = SoundManager.PlayAudioWithDistance("GravityVortex", transform.position);
			detonated = true;
		}
	}

	public override void Update()
	{
		base.Update();
		if (detonated && audioSource != null && !audioSource.isPlaying)
		{
			audioSource.Play();
		}
	}
