	{
		sprite.color = warningColor;
		SoundManager.PlayWithDistAndSPR("LaserOrbWindup", transform.position);
	}

	private void Update()
	{
		if (parentTrans != null)
		{
			transform.position = parentTrans.position;
		}
		if (!blastCalled && autoBlast && ChaosStopwatch.Check(autoStopwatchID))
		{
			Blast();
		}
	}

	public void AutoBlast(float givenTime = 0.25f)
	{
		autoBlast = true;
		autoStopwatchID = ChaosStopwatch.Begin(givenTime);
	}

	public void Blast()
	{
		if (!blastCalled)
		{
			blastCalled = true;
			anim.Play("Shoot", -1, 0f);
			sprite.color = Color.white;
			sprite.sortingLayerName = "Effect";
			SoundManager.PlayWithDistAndSPR("LaserOrbShoot", transform.position);
			CameraController.ShakeCamera(0.25f);
			if (gameObject != null)
			{
				Object.Destroy(gameObject, 0.25f);
			}
		}
	}

	public void Reset()
	{
		if (!blastCalled)
		{
			blastCalled = true;
			if (gameObject != null)
			{
				Object.Destroy(gameObject);
			}
		}
	}
}
