public class AirTrail : MonoBehaviour
{
	private static GameObject _prefab;

	public float duration = 1f;

	public int maxHitCount = 4;

	private int hitCDStopwatchID;

	private float hitDelay;

	[HideInInspector]
	public Attack attackBox;

	private Collider2D attackCollider;

	public static GameObject Prefab
	{
		get
		{
			if (_prefab == null)
			{
				_prefab = ChaosBundle.Get("Assets/Prefabs/PlayerSkills/AirTrail.prefab");
			}
			return _prefab;
		}
	}

	private void Awake()
	{
		attackBox = transform.Find("Attack").GetComponent<Attack>();
		attackCollider = attackBox.GetComponent<Collider2D>();
		attackCollider.enabled = false;
	}

	private void Start()
	{
		maxHitCount = Mathf.Max(0, maxHitCount);
		hitDelay = duration / (float)maxHitCount;
		hitCDStopwatchID = ChaosStopwatch.Begin(hitDelay, useInterval: true, hitDelay, maxHitCount);
	}

	private void Update()
	{
		switch (ChaosStopwatch.CheckInterval(hitCDStopwatchID))
		{
		case StopwatchState.Running:
			attackCollider.enabled = true;
			break;
		case StopwatchState.Ready:
			attackCollider.enabled = false;
			break;
		case StopwatchState.Done:
			Object.Destroy(gameObject);
			break;
		}
	}
