public class LightningStorm : MonoBehaviour
{
	private static GameObject _prefab;

	public string skillCategory = string.Empty;

	public string skillID = string.Empty;

	public int skillLevel;

	private Animator anim;

	private float radius;

	[HideInInspector]
	public bool overdriveReady;

	public float strikeDelay;

	public float strikeChance;

	public float pvpStrikeChance = 0.08f;

	[HideInInspector]
	public int strikeDelayStopwatchID = -1;

	[HideInInspector]
	public bool strikeAllTargets;

	[HideInInspector]
	public Entity parentEntity;

	[HideInInspector]
	public Health parentHealth;

	private List<GameObject> validTargets;

	[HideInInspector]
	public List<GameObject> doNotTargetList;

	public static GameObject _lightningPrefab;

	public GameObject currentStrike;

	[HideInInspector]
	public Vector3 ultPosition;

	private int targetIndex;

	public static GameObject Prefab
	{
		get
		{
			if (_prefab == null)
			{
				_prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/LightningStorm.prefab");
			}
			return _prefab;
		}
	}

	public static GameObject LightningPrefab
	{
		get
		{
			if (_lightningPrefab == null)
			{
				_lightningPrefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/LightningStrike.prefab");
			}
			return _lightningPrefab;
		}
	}

	private void Awake()
	{
		radius = GetComponent<SpriteRenderer>().sprite.bounds.max.x;
		radius *= transform.localScale.x;
		if (radius < 0f)
		{
			radius *= -1f;
		}
		anim = GetComponent<Animator>();
	}

	private void Update()
	{
		if (overdriveReady || parentEntity == null || (parentHealth != null && parentHealth.healthStat.CurrentValue <= 0f) || parentEntity.fsm.currentStateName.Contains("Dead") || parentEntity.fsm.currentStateName.Contains("Paused") || !ChaosStopwatch.Check(strikeDelayStopwatchID))
		{
			return;
		}
		strikeDelayStopwatchID = ChaosStopwatch.Begin(strikeDelay * Random.Range(0.8f, 1.2f));
		validTargets = Entity.GetAllTargetsInRange(GameController.enemies, transform.position, radius, playerTagOnly: false, doNotTargetList, parentEntity.gameObject);
		if (strikeAllTargets)
		{
			ultPosition = transform.position;
			if (validTargets.Count != 0)
			{
				foreach (GameObject validTarget in validTargets)
				{
					StrikeLocation(validTarget.transform.position);
				}
				return;
			}
			Vector2 vector = transform.position;
			Vector2 vec = default;
			float num = radius * 0.9f;
			StrikeLocation(vector + vec.Randomize(1f, num));
		}
		else
		{
			if (validTargets.Count == 0)
			{
				return;
			}
			if (GameController.pvpOn)
			{
				if (Random.value > pvpStrikeChance)
				{
					return;
				}
			}
			else if (Random.value > strikeChance)
			{
				return;
			}
			targetIndex = Random.Range(0, validTargets.Count);
			StrikeLocation(validTargets[targetIndex].transform.position);
			validTargets.Clear();
		}
	}

	public void StrikeLocation(Vector2 targetLoc)
	{
		currentStrike = Object.Instantiate(LightningPrefab, targetLoc, Quaternion.identity);
		currentStrike.transform.Find("AttackBox").GetComponent<Attack>().SetAttackInfo(skillCategory, skillID, skillLevel, strikeAllTargets);
		if (Random.value > 0.5f)
		{
			currentStrike.transform.localScale = new Vector3(-1f, 1f, 1f);
		}
	}

	public void SetAnimSpeed(float speed = 1f)
	{
		anim.speed = speed;
	}

	public void DestroySelf()
	{
		Object.Destroy(gameObject);
	}

	public void BoltDeluge()
	{
		StartCoroutine(UseBoltDeluge());
	}

	private IEnumerator UseBoltDeluge()
	{
		float ultDuration = 1.55f;
		float originalStrikeChance = strikeChance;
		float originalStrikeDelay = strikeDelay;
		strikeChance = 1f;
		strikeDelay = 0.1f;
		strikeAllTargets = true;
		strikeDelayStopwatchID = -1;
		ultPosition = transform.position;
		overdriveReady = false;
		yield return new WaitForSeconds(ultDuration);
		strikeChance = originalStrikeChance;
		strikeDelay = originalStrikeDelay;
		strikeAllTargets = false;
		SetAnimSpeed();
	}
}
