	{
		base.Start();
		stopLayerMask = ChaosCollisions.layerAllWall;
		Transform transform = base.transform.Find("ReflectWall");
		BoxCollider2D component = transform.GetComponent<BoxCollider2D>();
		component.size = new Vector2(1f, (float)maxWaveCount * spacing);
		component.offset = new Vector2(0f, (float)maxWaveCount * spacing * 0.5f);
		negateScript = transform.GetComponent<NegateProjectiles>();
		negateScript.parentObject = parentObject;
		negateScript.skillCategory = waveSkillCategory;
		negateScript.givenNormal = givenNormalVector;
		NegateProjectiles negateProjectiles = negateScript;
		negateProjectiles.reflectEventHandlers = (NegateProjectiles.ReflectEventHandler)Delegate.Combine(negateProjectiles.reflectEventHandlers, new NegateProjectiles.ReflectEventHandler(OnReflectAnim));
		transform.localPosition = -moveVector * spacing * 0.5f;
		transform.localEulerAngles = Globals.GetRotationVector(moveVector);
