		{
			Attack obj = wavePoolAttacks[i];
			obj.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Combine(obj.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(OnSlowAnim));
