	}

	private void OnSlowAnim(Collider2D col)
	{
		PlayReflectAnim();
	}

	private void OnReflectAnim(NegateProjectiles negate, Collider2D other)
	{
		PlayReflectAnim();
	}

	private void PlayReflectAnim()
	{
		for (int i = 0; i < maxWaveCount; i++)
		{
			if (wavePoolAnims[i] != null)
			{
				wavePoolAnims[i].Play("Reflect", -1, UnityEngine.Random.Range(0f, 0.25f));
			}
		}
	}
