using UnityEngine;

public class Snowman : Entity
{
	private bool spawning = true;

	private bool windingUp = true;

	private bool finishedAttacking;

	public float lifeTime;

	public float attackRange;

	private int lifeTimeStopwatchID = -1;

	private float lifeTimePercentage;

	private TargetInfo targetInfo;

	private Collider2D attackCol;

	private AnimationClip atkAnimClip;

	private float defaultAnimClipLen;

	private float defaultMoveSpeed;

	private NumVarStatMod moveSpeedUpMod;

	private Vector3 moveVector;

	private List<GameObject> excludeTargets;

	[HideInInspector]
	public GameObject parentObject;

	private Transform headTrans;

	private Transform bodyTrans;

	private Transform slashTrans;

	private Transform atkTrans;

	private Vector3 ogSlashPos;

	private Vector3 ogAtkPos;

	private Vector3 ogHeadPos;

	private Vector3 ogBodyPos;

	private Vector3 atkPos;

	private int maxHitCount = 999;

	private float defaultHitCooldownTime = 0.15f;

	private float hitCooldownTime = 0.15f;

	private int hitCDStopwatchID = -1;

	private Dictionary<GameObject, int> hitCounters;

	private int maxSnowEffectCount = 999;

	private int snowEffectStopwatchID = -1;

	private float snowEffectTime = 0.25f;

	private ParticleEffect snowEmitter;

	private int audioStopwatchID = -1;

	private float animSpeedMultiplier;

	private static GameObject _prefab;

	public static GameObject Prefab
	{
		get
		{
			if (_prefab == null)
			{
				_prefab = ChaosBundle.Get("Assets/Prefabs/Allies/Snowman.prefab");
			}
			return _prefab;
		}
	}

	public override void Awake()
	{
		base.Awake();
		attack = GetComponentInChildren<Attack>();
		attackCol = attack.GetComponent<Collider2D>();
		excludeTargets = new List<GameObject>();
		hitCounters = new Dictionary<GameObject, int>();
		atkAnimClip = anim.GetAnimClip("Attack");
		defaultAnimClipLen = atkAnimClip.length;
		defaultMoveSpeed = movement.moveSpeedStat.CurrentValue;
		headTrans = transform.Find("Head");
		ogHeadPos = headTrans.localPosition;
		bodyTrans = transform.Find("Body");
		ogBodyPos = bodyTrans.localPosition;
		slashTrans = transform.Find("SlashSprite");
		ogSlashPos = slashTrans.localPosition;
		atkTrans = transform.Find("AttackBox");
		ogAtkPos = atkTrans.localPosition;
		moveSpeedUpMod = new NumVarStatMod("SnowmanMoveSpeedUpMod", movement.moveSpeedStat.CurrentValue, 10, VarStatModType.OverrideWithMods);
	}

	public override void Start()
	{
		base.Start();
		Attack attack = base.attack;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(ExcludeTarget));
		snowEmitter = PoolManager.GetPoolItem<ParticleEffect>("SnowEmitter");
		snowEmitter.followTransform = bodyTrans;
		snowEmitter.followOffset = Vector3.up * 1f;
		snowEmitter.Play();
		SoundManager.PlayAudioWithDistance("SummonSnowman", transform.position);
	}

	public override void Update()
	{
		base.Update();
		if (spawning)
		{
			if (anim.AnimPlayed())
			{
				spawning = false;
				anim.Play("WindUp", -1, 0f);
			}
			return;
		}
		if (windingUp)
		{
			if (!anim.AnimPlayed())
			{
				return;
			}
			windingUp = false;
			hitCDStopwatchID = ChaosStopwatch.Begin(hitCooldownTime, useInterval: true, hitCooldownTime, maxHitCount - 1);
			snowEffectStopwatchID = ChaosStopwatch.Begin(snowEffectTime, useInterval: true, snowEffectTime, maxSnowEffectCount - 1);
			lifeTimeStopwatchID = ChaosStopwatch.Begin(lifeTime);
		}
		lifeTimePercentage = ChaosStopwatch.GetTimePercentage(lifeTimeStopwatchID);
		if (lifeTimePercentage >= 1f)
		{
			UnityEngine.Object.Destroy(gameObject);
			PoolManager.GetPoolItem<ParticleEffect>("SnowDebrisEmitter").Emit(10, transform.position + Vector3.up);
			PoolManager.GetPoolItem<ParticleEffect>("SnowDebrisEmitter").Emit(6, transform.position + Vector3.up * 1f);
			PoolManager.GetPoolItem<ParticleEffect>("SnowDebrisEmitter").Emit(6, transform.position + Vector3.up * 2f);
			return;
		}
		animSpeedMultiplier = 1f;
		if (lifeTimePercentage > 0.5f)
		{
			animSpeedMultiplier = Globals.LerpWithRange(0.5f, 1f, lifeTimePercentage, 0.66f, 2f);
		}
		else
		{
			animSpeedMultiplier = Globals.LerpWithRange(1f, 0.5f, lifeTimePercentage, 2f, 0.66f);
		}
		moveSpeedUpMod.modValue = defaultMoveSpeed / animSpeedMultiplier * 0.75f;
		movement.moveSpeedStat.AddMod(moveSpeedUpMod);
		if (ChaosStopwatch.Check(audioStopwatchID))
		{
			audioStopwatchID = ChaosStopwatch.Begin(Mathf.Lerp(0f, 0.25f, animSpeedMultiplier * 0.5f));
			SoundManager.PlayAudioWithDistance("StandardSpinSingle", transform.position);
		}
		hitCooldownTime = defaultHitCooldownTime * animSpeedMultiplier * 1.75f;
		ChaosStopwatch.SetIntervalTime(hitCDStopwatchID, hitCooldownTime);
		anim.AdjustAnimSpeed(atkAnimClip, defaultAnimClipLen * animSpeedMultiplier);
		StopwatchState stopwatchState = ChaosStopwatch.CheckInterval(snowEffectStopwatchID);
		if (stopwatchState == StopwatchState.Ready)
		{
			PoolManager.GetPoolItem<ParticleEffect>("SnowDebrisEmitter").Emit(2, transform.position + Vector3.up);
		}
		switch (ChaosStopwatch.CheckInterval(hitCDStopwatchID))
		{
		case StopwatchState.Ready:
			attackCol.enabled = false;
			break;
		case StopwatchState.Done:
			finishedAttacking = true;
			attackCol.enabled = false;
			enabled = false;
			break;
		}
		if (targetInfo == null || targetInfo.transform == null)
		{
			List<GameObject> enemies = GameController.enemies;
			Vector3 position = transform.position;
			float range = attackRange;
			List<GameObject> excludeList = excludeTargets;
			targetInfo = Entity.GetClosestTarget(enemies, position, range, playerTagOnly: false, excludeList, parentObject);
			if (targetInfo == null)
			{
				excludeTargets.Clear();
				excludeList = GameController.enemies;
				position = transform.position;
				range = attackRange;
				GameObject excludeTarget = parentObject;
				targetInfo = Entity.GetClosestTarget(excludeList, position, range, playerTagOnly: false, null, excludeTarget);
			}
			if (targetInfo == null)
			{
				return;
			}
		}
		movement.MoveToTarget(targetInfo.transform.position, 1f);
	}

	private new void OnDestroy()
	{
		ChaosStopwatch.Stop(hitCDStopwatchID);
		if (snowEmitter != null)
		{
			snowEmitter.Stop();
		}
		SoundManager.PlayAudioWithDistance("SummonSnowman", transform.position);
	}

	private new void FixedUpdate()
	{
		if (!spawning && !windingUp && !finishedAttacking)
		{
			attackCol.enabled = true;
		}
	}

	private new void LateUpdate()
	{
		if (!spawning && !windingUp)
		{
			atkPos = movement.moveVector.normalized * 0.125f;
			headTrans.transform.localPosition = atkPos * 2f + ogHeadPos;
			bodyTrans.transform.localPosition = atkPos + ogBodyPos;
			atkTrans.transform.localPosition = new Vector3(0f, 0.25f, 0f);
			slashTrans.transform.localPosition = atkPos + ogBodyPos;
		}
	}

	private void ExcludeTarget(Entity otherEntity)
	{
		if (otherEntity != null && !excludeTargets.Contains(otherEntity.gameObject))
		{
			if (hitCounters.ContainsKey(otherEntity.gameObject))
			{
				hitCounters[otherEntity.gameObject]++;
			}
			else
			{
				hitCounters[otherEntity.gameObject] = 1;
			}
			if (hitCounters[otherEntity.gameObject] >= 2)
			{
				excludeTargets.Add(otherEntity.gameObject);
				hitCounters[otherEntity.gameObject] = 0;
				targetInfo = null;
			}
		}
	}

	public void SpawnArmsAndFaceEffect()
	{
		PoolManager.GetPoolItem<ParticleEffect>("SnowDebrisEmitter").Emit(5, bodyTrans.position + Globals.Vector3UpRight);
		PoolManager.GetPoolItem<ParticleEffect>("SnowDebrisEmitter").Emit(5, bodyTrans.position + Globals.Vector3UpLeft);
		PoolManager.GetPoolItem<ParticleEffect>("SnowDebrisEmitter").Emit(5, headTrans.position + Vector3.up * 2f);
	}
}

