	private void LateUpdate()
	{
		for (int num = rbList.Count - 1; num >= 0; num--)
		{
			if (rbList[num] == null || Vector2.SqrMagnitude(rbList[num].transform.position - currentPosition) > sqEscRadius)
			{
				rbList.RemoveAt(num);
			}
		}
	}

	private void FixedUpdate()
	{
		currentPosition = transform.position;
		for (int num = rbList.Count - 1; num >= 0; num--)
		{
			currentRB = rbList[num];
			if (!(currentRB == null) && currentRB.bodyType != RigidbodyType2D.Static)
			{
				forceVector = (currentPosition - currentRB.transform.position).normalized * pullForce;
				currentRB.velocity = Vector2.ClampMagnitude(currentRB.velocity + forceVector, maxForce);
			}
		}
	}

	private void OnTriggerEnter2D(Collider2D col)
	{
