		}
		if (breakDelay != -1f)
		{
			Invoke("Break", breakDelay);
		}
		if (useDuration)
		{
			hitBoxActive = true;
			hitDurationStopwatchID = ChaosStopwatch.Begin(hitDuration);
			attackCollider.enabled = useAttackBox;
			floorCollider.enabled = useFloorCollider;
		}
		else
		{
			Break();
			attackCollider.enabled = false;
			floorCollider.enabled = false;
		}
	}
